console.log('Request Details:', JSON.stringify($json, null, 2));
let method = $json.method;
if (!method) {
  method = $json.headers[':method'] || 'POST';
}
return [{ json: { ...$json, method: method } }];

const data = $json;
console.log('Incoming form data ($json):', JSON.stringify(data, null, 2));
return [{ json: {
  departure: data.departure || 'Not specified',
  destination: data.destination || 'Not specified',
  startDate: data.startDate || 'N/A',
  endDate: data.endDate || 'N/A',
  dates: data.dates || 'Not specified',
  tripType: data.tripType || 'N/A',
  dayActivity: data.dayActivity || [],
  nightActivity: data.nightActivity || [],
  groupSize: data.groupSize || '1',
  ageRange: data.ageRange || [],
  budget: data.budget || '0',
  email: data.email || 'unknown'
} }];

const {
  departure,
  destination,
  startDate,
  endDate,
  dates,
  tripType,
  dayActivity,
  nightActivity,
  groupSize,
  ageRange,
  budget,
  email
} = $json;
console.log('Preparing prompt with departure:', departure);
return [{ json: {
  departure,
  destination,
  startDate,
  endDate,
  dates,
  tripType,
  dayActivity,
  nightActivity,
  groupSize,
  ageRange,
  budget,
  email,
  prompt: `You are an experienced and helpful AI travel agent specializing in tropical beach getaways. Your goal is to create exciting, practical, and well-organized travel itineraries tailored to each user's preferences. Be friendly, informative, and concise.
- Departure Location: ${departure}
- Destination: ${destination}
- Travel Dates: ${startDate} to ${endDate}
- Trip Type: ${tripType}
- Day Activities: ${Array.isArray(dayActivity) ? dayActivity.join(', ') : dayActivity || 'Not specified'}
- Night Activities: ${Array.isArray(nightActivity) ? nightActivity.join(', ') : nightActivity || 'Not specified'}
- Group Size: ${groupSize}
- Age Ranges: ${Array.isArray(ageRange) ? ageRange.join(', ') : ageRange || 'Not specified'}
- Budget: $${budget}

Create a complete itinerary for this tropical beach getaway. Include recommendations for:
1. Flights (specific airlines and routes from ${departure || 'the nearest major airport'} to ${destination}, with estimated costs)
2. Accommodation options (specific hotels or resorts matching the preferences, with estimated cost per night and total cost for the trip, and provide at least one alternative option)
3. Daily schedule with activities, dining options, and sights (include morning, afternoon, and evening plans for each day, incorporating the user's day and night activity preferences)
4. Estimated food budget (daily cost and recommendations for dining, considering local tropical cuisine)
5. A cost summary table (flights, accommodation, activities, food, total, and remaining budget). This section is mandatory and must always be included. If no costs are available, use placeholder values (e.g., Flights\t$0). Ensure the table includes all categories: Flights, Accommodation, Activities, Food, Total, and Remaining Budget, in that order.
6. Travel tips specific to the tropical destination and beach getaway experience

Respond in a clean and organized layout with sections. Include hyperlinks to flight bookings, accommodations, activities, or dining options where relevant, using <a href="URL">Description</a> format. Use real, functional URLs where users can book or learn more (e.g., hotel websites, activity providers). Do not use placeholder URLs like "https://example.com". Ensure the Cost Summary section is formatted as a tab-separated table (e.g., Flights\t$1,000).` }
}];

const tropical = $node['Prepare Tropical Data'].json;
const ai = $node['OpenAI'].json.message?.content || 'No itinerary found.';
console.log('Raw OpenAI output:', ai);
return [{ json: {
  departure: tropical.departure,
  destination: tropical.destination,
  startDate: tropical.startDate,
  endDate: tropical.endDate,
  dates: tropical.dates,
  tripType: tropical.tripType,
  dayActivity: tropical.dayActivity,
  nightActivity: tropical.nightActivity,
  groupSize: tropical.groupSize,
  ageRange: tropical.ageRange,
  budget: tropical.budget,
  email: tropical.email,
  itinerary: ai
} }];

const destination = $json.destination || 'Your Destination';
const travelDates = `${$json.startDate || 'N/A'} to ${$json.endDate || 'N/A'}`;
const departure = $json.departure || 'Not specified';
const tripType = $json.tripType || 'N/A';
const dayActivity = Array.isArray($json.dayActivity) ? $json.dayActivity.join(', ') : $json.dayActivity || 'Not specified';
const nightActivity = Array.isArray($json.nightActivity) ? $json.nightActivity.join(', ') : $json.nightActivity || 'Not specified';
const groupSize = $json.groupSize || 'N/A';
const ageRange = Array.isArray($json.ageRange) ? $json.ageRange.join(', ') : $json.ageRange || 'Not specified';
const budget = $json.budget || 'N/A';
let itineraryRaw = $json.itinerary || 'Itinerary details not available.';
console.log('Initial itineraryRaw:', itineraryRaw);
console.log('Checking for Cost Summary in itineraryRaw (case-insensitive)...');
if (!itineraryRaw.toLowerCase().includes('cost summary:')) {
  console.log('Cost Summary missing, adding fallback');
  itineraryRaw += '\n\nCost Summary:\nFlights\t$0\nAccommodation\t$0\nActivities\t$0\nFood\t$0\n<strong>Total</strong>\t<strong>$0</strong>\n<strong>Remaining Budget</strong>\t<strong>$' + budget + '</strong>';
} else {
  console.log('Cost Summary found in itineraryRaw');
}
console.log('itineraryRaw after fallback check:', itineraryRaw);
const itineraryLines = itineraryRaw.split('\n');
let itinerary = '';
let inTable = false;
let tableRows = [];
for (let line of itineraryLines) {
  line = line.trim();
  if (!line) {
    itinerary += '<br>';
    continue;
  }
  if (line.toLowerCase().startsWith('cost summary:')) {
    inTable = true;
    tableRows = [];
    itinerary += `<strong style="font-size: 16px; color: #2a4a6e; display: block; margin: 15px 0 5px 0;">${line}</strong>`;
    continue;
  }
  if (inTable && (line.startsWith('Total') || line.startsWith('Remaining Budget'))) {
    const [category, cost] = line.split('\t').map(item => item.trim());
    tableRows.push(`<tr><td style="border: 1px solid #e0e0e0; padding: 8px; background-color: #f0f0f0; font-weight: bold;">${category}</td><td style="border: 1px solid #e0e0e0; padding: 8px; background-color: #f0f0f0; font-weight: bold;">${cost}</td></tr>`);
    continue;
  }
  if (inTable && line.includes('\t')) {
    const [category, cost] = line.split('\t').map(item => item.trim());
    tableRows.push(`<tr><td style="border: 1px solid #e0e0e0; padding: 8px;">${category}</td><td style="border: 1px solid #e0e0e0; padding: 8px;">${cost}</td></tr>`);
    continue;
  }
  if (inTable && !line.includes('\t')) {
    inTable = false;
    itinerary += `<table style="border-collapse: collapse; width: 100%; margin: 10px 0; font-size: 14px;" cellpadding="0" cellspacing="0">${tableRows.join('')}</table><br>`;
  }
  if (!inTable) {
    if (line.endsWith(':')) {
      itinerary += `<strong style="font-size: 16px; color: #2a4a6e; display: block; margin: 15px 0 5px 0;">${line}</strong>`;
    } else {
      itinerary += line + '<br>';
    }
  }
}
if (inTable) {
  itinerary += `<table style="border-collapse: collapse; width: 100%; margin: 10px 0; font-size: 14px;" cellpadding="0" cellspacing="0">${tableRows.join('')}</table><br>`;
}
console.log('Final itinerary HTML:', itinerary);
const subject = `Your Tropical Itinerary for ${destination} - Voyage Genie`;
const message = `<div style="font-family: 'Helvetica Neue', Arial, sans-serif; max-width: 600px; margin: 0 auto; background-color: #f7f7f7; padding: 25px; border-radius: 10px; box-shadow: 0 4px 8px rgba(0,0,0,0.1);"><div style="background-color: #2a4a6e; padding: 20px; border-radius: 10px 10px 0 0; text-align: center;"><h1 style="color: #ffffff; margin: 0; font-size: 28px;">🌴 Your Tropical Itinerary</h1></div><div style="padding: 25px; background-color: #ffffff; border-radius: 0 0 10px 10px;"><h2 style="color: #2a4a6e; font-size: 22px; margin: 0 0 15px 0; text-align: left;">Departing from: ${departure}</h2><h2 style="color: #2a4a6e; font-size: 22px; margin: 0 0 15px 0; text-align: left;">Destination: ${destination}</h2><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Travel Dates:</strong> ${travelDates}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Trip Type:</strong> ${tripType}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Day Activities:</strong> ${dayActivity}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Night Activities:</strong> ${nightActivity}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Age Range:</strong> ${ageRange}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Budget:</strong> $${budget} (for ${groupSize} travelers)</p><hr style="border: 0; border-top: 1px solid #e0e0e0; margin: 25px 0;"><h3 style="color: #2a4a6e; font-size: 18px; margin: 0 0 15px 0; text-align: left;">Itinerary Details</h3><div style="background-color: #f9f9f9; padding: 20px; border-radius: 6px; font-size: 14px; line-height: 1.6; color: #333333;">${itinerary}</div><hr style="border: 0; border-top: 1px solid #e0e0e0; margin: 25px 0;"><p style="color: #666666; font-size: 12px; text-align: center; margin: 0;">Generated by <strong>Voyage Genie</strong> 🌟</p></div></div>`;

const sessionId = Date.now().toString();
console.log('Returning itineraryHtml directly with sessionId:', sessionId);

return [{ json: { sessionId: sessionId, itineraryHtml: message, resolvedEmail: $json.email || 'jtran112675@gmail.com', resolvedSubject: subject, resolvedMessage: message, formData: { departure: departure, destination: destination, startDate: $json.startDate, endDate: $json.endDate, budget: budget, groupSize: groupSize } } }];

const url = 'https://exodonprofits.app.n8n.cloud/webhook/send-email';
const payload = {
  resolvedEmail: $json.resolvedEmail,
  resolvedSubject: $json.resolvedSubject,
  resolvedMessage: $json.resolvedMessage
};
try {
  const response = await $http({
    method: 'POST',
    url: url,
    body: payload,
    headers: { 'Content-Type': 'application/json' }
  });
  console.log('Email trigger response:', response);
} catch (error) {
  console.error('Error triggering email workflow:', error.message);
}
return $input.all();
